Rules.InvariantScript:
Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
UpdateContext({locSupRuleId: Blank(), locSupSource: "", locSupDays: 90});

// Expiry is chosen as a duration rather than a calendar date: it removes a control
// whose property surface is unverified, and it enforces the configured cap by
// construction — every option is inside SuppressionMaxDays.
// Built in ONE statement. Filtering a collection while ClearCollect-ing into
// that same collection empties it: ClearCollect clears first, so the Filter
// then reads nothing. That is what left the expiry picker blank.
ClearCollect(
    colSupDuration,
    Filter(
        Table(
            {Days: 30, Label: "30 days"},
            {Days: 60, Label: "60 days"},
            {Days: 90, Label: "90 days"},
            {Days: 180, Label: "180 days"},
            {Days: 365, Label: "365 days"}
        ),
        Days <= Coalesce(gblCfg.SuppressionMaxDays, 365)
    )
);

// There is no usp_GetSuppressibleRules; the rule list serves the picker.
IfError(
    ClearCollect(
        colSupRules,
        Filter(
        db_dq_sandbox.dquspGetRuleList(
            {
                ActorUpn: gblActorUpn,
                ActiveOnly: true,
                DomainCode: Blank(),
                TargetLayer: Blank(),
                Page: 1,
                PageSize: 200
            }
        ).ResultSets.Table1,
            !IsBlank(RuleId)
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not load rules", Detail: FirstError.Message})
);
Set(gblBusy, false)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspRequestSuppression(
                {
                    ActorUpn: gblActorUpn,
                    RuleId: locSupRuleId,
                    // CONTRACT GAP 11: the expected ScopeJson shape is undocumented.
                    // There is no SourceSystem parameter, so the source selection is
                    // carried here. Confirm the shape the procedure parses.
                    ScopeJson: "{""SourceSystem"":""" & locSupSource & """}",
                    Reason: Trim(txtReasonSU.Text),
                    ExpiresAt: Text(DateAdd(Today(), locSupDays, TimeUnit.Days), "yyyy-mm-dd")
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "The request was not submitted", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Notify("Suppression requested. An approver will decide.", NotificationType.Success, 4000);
    Back(),
    Notify(Coalesce(gblWriteResult.Message, "The request was not submitted."), NotificationType.Error, 6000)
);
Set(gblBusy, false)
